ame state.\n        valid_moves (List[int]): Indices of available actions.\n\n    Returns:\n        Index of the selected action from valid_moves.\n    \"\"\"\n        # Handle empty valid_moves to prevent IndexError\n        if not valid_moves:\n            raise ValueError(\"No valid moves available in the current state.\")\n\n        if random.uniform(0, 1) < self.epsilon:\n            return random.choice(valid_moves)\n\n        max_q = float('-inf')\n        best_actions: List[int] = []\n        q_values_for_state: Dict[Tuple[int, ...], List[float]] = {self._state_to_key(state): [0.0] * 9}\n        \n        for i in range(len(valid_moves)):\n            action_idx: int = valid_moves[i]\n            # Use cached Q-values or default to zero\n            q_val: float = q_values_for_state.get(self._state_to_key(state), [0.0])[action_idx] if action_idx < len(q_values_for_state.get(self._state_to_key(state), [0.0])) else 0.0\n            \n            if val := q_val:\n                if val > max_q + 1e-06:\n                    max_q = val\n                    best_actions: List[int] = [action_idx]\n                elif abs(val - max_q) < 1e-06:\n                    best_actions.append(action_idx)\n            else:\n                # Q-value is zero, treat as equal to current max if max_q is also effectively zero\n                if max_q == 0.0:\n                    pass # Keep existing best actions or add this one if none exist\n                elif val > max_q + 1e-06:\n                    max_q = val\n                    best_actions = [action_idx]\n                else:\n                    best_actions.append(action_idx)\n            \n            # Ensure we have at least one action to select from\n            if not best_actions and valid_moves:\n                best_actions = [valid_moves[0]]\n\n        if not best_actions:\n            return random.choice(valid_moves)\n        return random.choice(best_actions)\n\n    def update(self, state: List[int], action: int, reward: float, next_state: List[int]) -> None:\n        \"\"\"Updates the Q-value for the given state-action pair.\n\n    Args:\n        state (List[int]): Current game state.\n        action (int): Index of the action taken in the current state.\n        reward (float): Reward received after taking the action.\n        next_state (List[int]): Resulting game state after the action.\n\"\"\"\n        row: int = action // 3\n        col: int = action % 3\n        key: Tuple[int, ...] = self._state_to_key(state)\n        if key not in self.q_table:\n            self.q_table[key]: List[float] = [0.0] * 9\n        q_values: List[float] = self.q_table[key]\n        next_key: Tuple[int, ...] = self._state_to_key(next_state)\n        if next_key not in self.q_table:\n            self.q_table[next_key]: List[float] = [0.0] * 9\n        next_q_values: List[float] = self.q_table[next_key]\n        \n        current_max: float = max(q_values) if q_values else 0.0\n        next_max: float = max(next_q_values) if next_q_values else 0.0\n        td_target: float = reward + self.gamma * next_max\n        delta: float = td_target - current_max\n        act_idx: int = row * 3 + col\n        \n        if act_idx < len(q_values):\n            q_values[act_idx] += self.lr * delta\n\n    def decay_epsilon(self) -> None:\n        \"\"\"Decreases epsilon towards epsilon_end.\"\"\"\n        self.epsilon: float = max(self.epsilon * self.epsilon_decay, self.epsilon_end)\n\n    def _state_to_key(self, state: List[int]) -> Tuple[int, ...]:\n        \"\"\"Converts state list to tuple key for dictionary lookup.\"\"\"\n        return tuple(state)",
