sv_path = os.path.join(results_dir, 'results.csv')\n    with open(csv_path, 'w', newline='') as f:\n        writer = csv.writer(f)\n        writer.writerow(['method', 'metric', 'value'])\n        writer.writerow(['Q-Learning', 'win_rate', results['win_rate']])\n        writer.writerow(['Q-Learning', 'avg_reward', results['avg_reward']])\n",
