 num_games_played > 0:\n        win_rate = float(wins / num_games_played)\n        avg_reward = float(total_reward / num_games_played)\n    else:\n        win_rate = 0.0\n        avg_reward = 0.0\n    return {'win_rate': win_rate, 'avg_reward': avg_reward}\n\ndef run() -> None:\n    \"\"\"Main entrypoint for the experiment. Runs training and evaluation, saving results.\n\n    Executes training and evaluation using seed settings from config,\n    writes CSV results, and ensures the results directory exists.\n\n    Returns:\n        None.\n    \"\"\"\n    from qagent import QLearningAgent\n    from opponent import RandomOpponent\n    from config import LEARNING_RATE, DISCOUNT_FACTOR, EPSILON_START, EPSILON_END, EPSILON_DECAY, MAX_EPISODES, NUM_EVAL_GAMES, TRAIN_SEED, EVAL_SEED, get_results_dir\n    np.random.seed(TRAIN_SEED)\n    train_agent(QLearningAgent(learning_rate=LEARNING_RATE, discount_factor=DISCOUNT_FACTOR, epsilon_start=EPSILON_START, epsilon_end=EPSILON_END, epsilon_decay=EPSILON_DECAY))\n    eval_agent = QLearningAgent(learning_rate=LEARNING_RATE, discount_factor=DISCOUNT_FACTOR, epsilon_start=EPSILON_START, epsilon_end=EPSILON_END, epsilon_decay=EPSILON_DECAY)\n    results = evaluate_agent(eval_agent)\n    results_dir = get_results_dir()\n    os.makedirs(results_dir, exist_ok=True)\n    csv_path = os.path.join(results_dir, 'results.csv')\n    with open(csv_path, 'w', newline='') as f:\n        writer = csv.writer(f)\n        writer.writerow(['method', 'metric', 'value'])\n        for metric_name in ['win_rate', 'avg_reward']:\n            if metric_name in results:\n                value = results[metric_name]\n                writer.writerow(['QLearningAgent', f\"{metric_name}_agent_metric_{metric_name.replace('_', '_')}\"], metric_name, str(value))\n",
