  "existing_content": "\"\"\"Experiment module: trains Q-Learning agent against a random opponent and evaluates performance.\"\"\"\nimport random\nimport csv\nimport os\nfrom typing import Dict, Optional\nimport numpy as np\nfrom config import LEARNING_RATE, DISCOUNT_FACTOR, EPSILON_START, EPSILON_END, EPSILON_DECAY, MAX_EPISODES, NUM_EVAL_GAMES, TRAIN_SEED, EVAL_SEED, get_results_dir\nfrom env import TicTacToeEnv\nfrom qagent import QLearningAgent\nfrom opponent import RandomOpponent\n\ndef train_agent(agent: Optional['QLearningAgent']=None) -> None:\n    \"\"\"Trains the Q-Learning agent against a Random Opponent.\n\n    Runs MAX_EPISODES episodes with configuration hyperparameters.\nThe episode loop correctly handles turn-taking between the agent and the opponent,\nupdating the state after every move until game over or max episodes reached.\n\nArgs:\n        agent: The Q-Learning agent to train. If None, a new instance is created.\n\nReturns:\n        None. Updates the passed agent in-place (or creates it if not provided).\n    \"\"\"\n    from qagent import QLearningAgent\n    from opponent import RandomOpponent\n    if agent is None:\n        agent = QLearningAgent(learning_rate=LEARNING_RATE, discount_factor=DISCOUNT_FACTOR, epsilon_start=EPSILON_START, epsilon_end=EPSILON_END, epsilon_decay=EPSILON_DECAY)\n    np.random.seed(TRAIN_SEED)\n    env = TicTacToeEnv()\n    opponent = RandomOpponent(player_symbol=1)\n    for episode in range(MAX_EPISODES):\n        state = env.reset()\n        game_over = False\n        total_episode_reward = 0.0\n        while not game_over:\n            valid_moves = env.get_valid_moves()\n            if len(valid_moves) == 0:\n                break\n            action = agent.choose_action(state, valid_moves)\n            new_state, reward, done = env.step(action)\n            total_episode_reward += reward\n            state = new_state\n            if done:\n                game_over = True\n                agent.decay_epsilon()\n                break\n            opp_move_idx = opponent.choose_action(valid_moves)\n            obs_next = env.step(opp_move_idx)\n            state = obs_next[0]\n\ndef evaluate_agent(agent: Optional['QLearningAgent']=None) -> Dict[str, float]:\n    \"\"\"Evaluate the agent against a random opponent in NUM_EVAL_GAMES games.\n\n    Args:\n        agent: The Q-Learning agent to evaluate. If None, a new instance is created.\n\n    Returns:\n        Dictionary containing 'win_rate' and 'avg_reward'.\n    \"\"\"\n    from qagent import QLearningAgent\n    if agent is None:\n        agent = QLearningAgent(learning_rate=LEARNING_RATE, discount_factor=DISCOUNT_FACTOR, epsilon_start=EPSILON_START, epsilon_end=EPSILON_END, epsilon_decay=EPSILON_DECAY)\n    np.random.seed(EVAL_SEED)\n    wins = 0\n    total_reward = 0.0\n    num_games_played = 0\n    agent_player_symbol = 1\n    for _ in range(NUM_EVAL_GAMES):\n        env = TicTacToeEnv()\n        state = env.reset()\n        game_over = False\n        episode_reward = 0.0\n        game_length = 0\n        while not game_over:\n            valid_moves = env.get_valid_moves()\n            if len(valid_moves) == 0:\n                break\n            action_idx = agent.choose_action(state, valid_moves)\n            new_state, reward, done = env.step(action_idx)\n            episode_reward += reward\n            game_length += 1\n            state = new_state\n            if done:\n                game_over = True\n                break\n            opp_move_idx = random.choice(valid_moves)\n            opp_new_state, _, _ = env.step(opp_move_idx)\n            state = opp_new_state\n        if game_over:\n            num_games_played += 1\n            if env.winner == agent_player_symbol:\n                wins += 1\n            normalized_reward = episode_reward / max(game_length, 1)\n            total_reward += normalized_reward\n    if num_games_played > 0:\n        win_rate = float(wins / num_games_played)\n        avg_reward = float(total_reward / num_games_played)\n    else:\n        win_rate = 0.0\n        avg_reward = 0.0\n    return {'win_rate': win_rate, 'avg_reward': avg_reward}\n\ndef run() -> None:\n    \"\"\"Main entrypoint for the experiment. Runs training and evaluation, saving results.\n\n    Executes training and evaluation using seed settings from config,\n    writes CSV results, and ensures the results directory exists.\n\n    Returns:\n        None.\n    \"\"\"\n    import sys\n    from qagent import QLearningAgent\n    from opponent import RandomOpponent\n    from env import TicTacToeEnv\n    from config import LEARNING_RATE, DISCOUNT_FACTOR, EPSILON_START, EPSILON_END, EPSILON_DECAY, MAX_EPISODES, NUM_EVAL_GAMES, TRAIN_SEED, EVAL_SEED, get_results_dir\n    np.random.seed(TRAIN_SEED)\n    train_agent(QLearningAgent(learning_rate=LEARNING_RATE, discount_factor=DISCOUNT_FACTOR, epsilon_start=EPSILON_START, epsilon_end=EPSILON_END, epsilon_decay=EPSILON_DECAY))\n    eval_agent = QLearningAgent(learning_rate=LEARNING_RATE, discount_factor=DISCOUNT_FACTOR, epsilon_start=EPSILON_START, epsilon_end=EPSILON_END, epsilon_decay=EPSILON_DECAY)\n    results = evaluate_agent(eval_agent)\n    results_dir = get_results_dir()\n    os.makedirs(results_dir, exist_ok=True)\n    csv_path = os.path.join(results_dir, 'results.csv')\n    with open(csv_path, 'w', newline='') as f:\n        writer = csv.writer(f)\n        writer.writerow(['method', 'metric', 'value'])\n        for metric_name in ['win_rate', 'avg_reward']:\n            if metric_name in results:\n                value = results[metric_name]\n                writer.writerow(['QLearningAgent', f\"{metric_name}_agent_metric_{metric_name.replace('_', '_')}\", metric_name, str(value)])\n",
