    def get_q_value(self, state: State, action: Action) -> float:
        """Get Q-value for state-action pair."""
        if state not in self.q_table or (state, action) not in self.q_table:
            return 0.0
        return self.q_table[(state, action)]

    def set_q_value(self, state: State, action: Action, value: float):
        """Set Q-value for state-action pair."""
        if (state, action) not in self.q_table:
            self.q_table[(state, action)] = 0.0
        self.q_table[(state, action)] = value

    def select_action(self, state: State, opponent: "TicTacToeQLearningAgent" | RandomOpponent, epsilon: float = 0.1) -> Action:
        """Select action using epsilon-greedy policy."""
        if random.random() < epsilon:
            available_actions = [Action(i) for i in range(9) if state.board[i // 3][i % 3] == "_"]
            return random.choice(available_actions)

        available_actions = [Action(i) for i in range(9) if state.board[i // 3][i % 3] == "_"]
        q_values = []
        for a in available_actions:
            val = self.get_q_value(state, a)
            q_values.append(val)

        return max(available_actions, key=lambda a: q_values[available_actions.index(a)])

    def update(self, state: State, action: Action, next_state: State, reward: int):
        """Update Q-value using standard Q-learning update rule."""
        current_q = self.get_q_value(state, action)
