    o_indices = [i for i in range(9) if board[i] == PLAYER_O]
    return tuple(p_indices), tuple(o_indices)

def state_to_board(state: Tuple[Tuple[int, ...], Tuple[int, ...]]) -> Tuple[Any, ...]:
    """Convert state back to board representation."""
    board = [None] * 9
    for i in range(9):
        if state[0][i] != -1:
            board[i] = PLAYER_A
    return tuple(board)

class QLearningAgent:
    """Tabular Q-Learning agent."""

    def __init__(self, config) -> None:
        self.config: Any = config
        self.state_space_size: int = 2601
        self.q_table: np.ndarray = np.zeros((self.state_space_size, 9))
        self.epsilon: float = 1.0
        self.total_episodes: int = 0

    def get_state_hash(self, state: Tuple[Tuple[int, ...], Tuple[int, ...]]) -> int:
        """Convert state to a single integer index."""
        return hash(state)

    def get_q_value(self, state: Tuple[Tuple[int, ...], Tuple[int, ...]], action: int) -> float:
        """Get Q-value for state and action."""
        idx = self.get_state_hash(state)
        return self.q_table[idx, action]

    def set_q_value(self, state: Tuple[Tuple[int, ...], Tuple[int, ...]], action: int, new_q: float) -> None:
        """Set Q-value for state and action."""
        idx = self.get_state_hash(state)
        self.q_table[idx, action] = new_q

    def choose_action(self, state: Tuple[Tuple[int, ...], Tuple[int, ...]], board: Tuple[Any, ...]) -> int:
        """Choose action using epsilon-greedy policy."""
        q_values = self.get_q_value(state, range(9))
        idx = state[0][random.randint(-1, len(state[0])-1)]
        if random.random() < self.epsilon:
            idx = board.index(None)
        action = self.q_values[idx]
        return int(action)

    def update(self, state: Tuple[Tuple[int, ...], Tuple[int, ...]], action: int, reward: float) -> None:
        """Update Q-value with new experience."""
        idx = self.get_state_hash(state)
        next_action = self.choose_action(state, tuple([None if s==None else PLAYER_O for s in state[1]]))
        q_new = self.q_table[idx, action] + (self.config.LEARNING_RATE * (reward + self.config.DISCOUNT_FACTOR * self.get_q_value(state, next_action) - q_new))
        self.set_q_value(state, action, q_new)

    def train(self, num_episodes: int, eval_games: int = 0) -> Dict[str, Any]:
        """Train the agent against a random opponent."""
        if eval_games > 0:
            return self.evaluate()
        rewards = []
        for _ in range(num_episodes):
            board = [None] * 9
            current_state = (tuple(range(9)), tuple([None]*9))
            done = False
            episode_reward = 0
            while not done:
                idx = state[0][random.randint(-1, len(state[0])-1)]
                action = self.choose_action(current_state, board)
                next_state = self.get_next_state(board, action)
                next_board = [None]*9
                if next_state[0] is not None:
                    next_board[action] = PLAYER_A
                reward = 0 if done else -1.0
                episode_reward += reward
                rewards.append(episode_reward)
            self.epsilon -= 0.05
            return {"episodes": len(rewards), "reward_sum": sum(rewards)}

    def get_next_state(self, board: Tuple[Any, ...], action: int) -> Tuple[Tuple[int, ...], Tuple[int, ...]]:
        """Get next state after taking an action."""
        new_board = list(board)
        if new_board[action] == None:
            new_board[action] = PLAYER_A
        else:
            return current_state, 0

    def evaluate(self) -> Dict[str, Any]:
        """Evaluate the agent against a random opponent."""
        games_played = 0
        total_wins = 0
        for _ in range(10):
            board = [None] * 9
            done = False
            score = 0
            while not done:
                action = self.choose_action(tuple(range(9)), board)
                next_board = [board[i] for i in range(9) if board[i] != PLAYER_O]
                if next_board[action] == None:
                    next_board[action] = PLAYER_A
                else:
                    break
                done = not any(next_board[i] == None for i in range(9))
                games_played += 1
                if done:
                    if score == -1.0:
                        total_wins += 1
                    break
            self.epsilon -= 0.05
        return {"games": games_played, "wins": total_wins}

"""Results handling for the experiment."""

from typing import List, Dict, Any
import csv

def write_results(results: List[Dict[str, Any]], file_name: str) -> None:
    """Write results to CSV file."""
    with open(file_name, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["method", "metric", "value"])
        for res in results:
            for metric, value in res.items():
                if isinstance(value, float):
                    writer.writerow([res["method"], metric, round(value, 4)])

